<?php

declare(strict_types=1);

namespace App\Services;

use App\Models\VpnUser;
use App\Models\Mikrotik;
use Illuminate\Support\Facades\Log;

/**
 * Generates /etc/ppp/chap-secrets content from database.
 */
class ChapSecretsGeneratorService
{
    /**
     * Generate chap-secrets file content.
     */
    public function generate(): string
    {
        $lines = [
            '# Secrets for PPP connections',
            '# Generated by VPN Panel',
            '# ' . now()->toDateTimeString(),
            '#',
            '# Format: "username" server "password" ip_address',
            '#',
        ];

            $seen = [];

            // Add VPN users (skip any that are already represented by a MikroTik)
            $mikrotikUsernames = Mikrotik::pluck('vpn_username')->all();

            $vpnUsers = VpnUser::active()
                    ->whereNotNull('assigned_ip')
                    ->orderBy('username')
                    ->get();

            foreach ($vpnUsers as $user) {
                    $key = $user->username . '@' . $user->assigned_ip;
                    if (in_array($user->username, $mikrotikUsernames, true) || isset($seen[$key])) {
                        continue;
                    }
                    $seen[$key] = true;

                    $username = $this->escapeUsername($user->username);
                    $password = $this->escapePassword($user->password);
                    $ip = $user->assigned_ip;

                    $lines[] = "\"{$username}\" l2tpd \"{$password}\" {$ip}";
            }

            // Add MikroTik entries (they use the same chap-secrets)
            $mikrotiks = Mikrotik::orderBy('vpn_username')
                    ->get();

            foreach ($mikrotiks as $mikrotik) {
                    $key = $mikrotik->vpn_username . '@' . $mikrotik->vpn_ip;
                    if (isset($seen[$key])) {
                        continue;
                    }
                    $seen[$key] = true;

                    $username = $this->escapeUsername($mikrotik->vpn_username);
                    $password = $this->escapePassword($mikrotik->vpnPassword());
                    $ip = $mikrotik->vpn_ip;

                    $lines[] = "\"{$username}\" l2tpd \"{$password}\" {$ip}";
            }

            return implode("\n", $lines) . "\n";
        }

    /**
     * Validate chap-secrets format.
     */
    public function validate(string $content): array
    {
        $errors = [];
        $lines = explode("\n", $content);

        foreach ($lines as $lineNum => $line) {
            $line = trim($line);

            // Skip empty lines and comments
            if ($line === '' || str_starts_with($line, '#')) {
                continue;
            }

            // Must match: "username" server "password" ip
            if (! preg_match('/^"([^"]+)"\s+\S+\s+"([^"]+)"\s+(\d+\.\d+\.\d+\.\d+)$/', $line, $matches)) {
                $errors[] = "Line {$lineNum}: Invalid format: {$line}";
                continue;
            }

            $username = $matches[1];
            $ip = $matches[3];

            // Validate IP
            if (! filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
                $errors[] = "Line {$lineNum}: Invalid IP address: {$ip}";
            }

            // Validate username (alphanumeric, hyphen, underscore)
            if (! preg_match('/^[a-zA-Z0-9_-]+$/', $username)) {
                $errors[] = "Line {$lineNum}: Invalid username: {$username}";
            }
        }

        return $errors;
    }

    private function escapeUsername(string $username): string
    {
        return str_replace(['"', '\\', "\n", "\r"], '', $username);
    }

    private function escapePassword(string $password): string
    {
        return str_replace(['"', '\\', "\n", "\r"], '', $password);
    }
}
